using System;
using System.Collections.Generic;
using Godot;

namespace DaggerCave;

/// <summary>
/// One creature's sprite sheet (generated by tools/sprites) turned into SpriteFrames. Animations
/// come in facing pairs ("run_r" / "run_l") plus facing transitions ("turn_r2l", "turn_l2r").
/// </summary>
public sealed class SpriteSet
{
    public SpriteFrames Frames;
    public Vector2 Origin;       // sheet pixels: where the gameplay origin sits inside a frame
    public float Scale;          // sheet pixels per world pixel
    public readonly HashSet<string> Names = new();

    private static readonly Dictionary<string, SpriteSet> Cache = new();

    /// <summary>Adds a clip (both facings) of <paramref name="frames"/> frames, borrowing the first frame of another.</summary>
    public SpriteSet AddClip(string name, int frames, string like)
    {
        foreach (var side in new[] { "_r", "_l" })
        {
            string src = like + side;
            if (!Frames.HasAnimation(src)) continue;
            Frames.AddAnimation(name + side);
            Frames.SetAnimationSpeed(name + side, 24);
            Frames.SetAnimationLoop(name + side, false);
            var tex = Frames.GetFrameTexture(src, 0);
            for (int k = 0; k < frames; k++) Frames.AddFrame(name + side, tex);
            Names.Add(name + side);
        }
        return this;
    }

    public static SpriteSet Get(string name)
    {
        if (Cache.TryGetValue(name, out var s)) return s;
        // (the Aegis shares the Vitalist's clip timings: its body is the 3D model, the sheet only says how long each clip runs)
        s = Load(name == "aegis" ? "vitalist" : name == "shapeshifter" ? "swordsman" : name == "crab_foe" ? "crab" : name);
        // (the reef crab shares the little crab's sheet, and adds the clips of its claws: the sheet only says how long each runs)
        if (name == "crab_foe") s.AddClip("pinch_windup", 10, "idle").AddClip("pinch", 6, "idle");
        // (the clips of the telegraphs the 3D models act out: the sheet only says how long each runs)
        if (name == "frog") s.AddClip("tongue_windup", 8, "idle");
        if (name == "spider") s.AddClip("pounce_windup", 8, "idle");
        if (name == "bat") s.AddClip("flare", 8, "fly");
        Cache[name] = s;
        return s;
    }

    private static SpriteSet Load(string name)
    {
        var tex = GD.Load<Texture2D>($"res://DaggerCave/Art/{name}.png");
        var text = FileAccess.GetFileAsString($"res://DaggerCave/Art/{name}.json");
        var meta = Json.ParseString(text).AsGodotDictionary();
        int fw = (int)meta["frame_w"], fh = (int)meta["frame_h"], cols = (int)meta["columns"];
        var origin = meta["origin"].AsGodotArray();
        var set = new SpriteSet
        {
            Origin = new Vector2((float)origin[0], (float)origin[1]),
            Scale = (float)meta["scale"],
            Frames = new SpriteFrames(),
        };
        float fps = (float)meta["fps"];
        set.Frames.RemoveAnimation("default");
        var atlasCache = new Dictionary<int, AtlasTexture>();
        foreach (var kv in meta["animations"].AsGodotDictionary())
        {
            string anim = (string)kv.Key;
            var def = kv.Value.AsGodotDictionary();
            set.Frames.AddAnimation(anim);
            set.Frames.SetAnimationSpeed(anim, fps);
            set.Frames.SetAnimationLoop(anim, (bool)def["loop"]);
            foreach (var fi in def["frames"].AsGodotArray())
            {
                int i = (int)fi;
                if (!atlasCache.TryGetValue(i, out var at))
                {
                    at = new AtlasTexture { Atlas = tex, Region = new Rect2((i % cols) * fw, (i / cols) * fh, fw, fh) };
                    atlasCache[i] = at;
                }
                set.Frames.AddFrame(anim, at);
            }
            set.Names.Add(anim);
        }
        return set;
    }
}

/// <summary>
/// Plays a <see cref="SpriteSet"/> on an AnimatedSprite2D with the conventions every creature
/// uses: a looping "base" animation chosen by gameplay state, prioritized one-shots layered on
/// top (land, attack, hurt...), automatic turn-around transitions when the facing changes, a
/// white hit-flash, and a detachable death animation that outlives the gameplay node.
/// </summary>
public partial class SpriteAnimator : Node2D
{
    private static Shader _flashShader;

    public AnimatedSprite2D Sprite;
    public SpriteSet Sheet;
    public int Facing = 1;          // the facing the sprite currently shows
    public bool AllowTurns = true;
    public float BaseSpeed = 1f;
    /// <summary>Extra playback multiplier (the enemy difficulty tempo).</summary>
    public float TimeMult = 1f;

    private string _base = "idle";
    private string _once;
    private int _oncePriority;
    private float _onceSpeed = 1f;
    private bool _turning;
    private int _targetFacing = 1;
    private ShaderMaterial _mat;
    private float _flash;
    private bool _manual;

    // ---- squash & stretch ("juice"): a springy scale on top of the sprite's own size
    private Vector2 _baseMag = Vector2.One;       // the sprite's scale magnitude without juice
    private Vector2 _punch = Vector2.One, _punchVel;
    private Vector2 _motion = Vector2.One, _motionTarget = Vector2.One;
    /// <summary>Distance from the origin down to the feet: squashes are anchored there.</summary>
    public float FootOffset = 10f;
    /// <summary>1 = normal, 0 = no squash and stretch (critters, stationary things).</summary>
    public float Juice = 1f;

    /// <summary>Kicks the springy scale (e.g. (1.3, 0.7) squashes, (0.8, 1.25) stretches); it
    /// overshoots and wobbles back.</summary>
    public void Punch(Vector2 scale)
    {
        _punch = Vector2.One + (scale - Vector2.One) * Juice;
        _punchVel = Vector2.Zero;
    }

    /// <summary>Continuous stretch from movement: long when falling or leaping, wide when running.</summary>
    public void Motion(Vector2 velocity)
    {
        float sy = 1 + Math.Clamp(Math.Abs(velocity.Y) / 700f, 0, 0.2f) * Juice;
        float sx = 1 + Math.Clamp(Math.Abs(velocity.X) / 1400f, 0, 0.1f) * Juice;
        _motionTarget = new Vector2(sx / MathF.Sqrt(sy), sy / MathF.Sqrt(sx));
    }

    // wind-ups hold a coiled squash for as long as they play; strikes pop a stretch
    private static bool IsWindup(string n) => n.Contains("windup") || n == "crouch";
    private static bool IsStrike(string n) => n is "strike" or "slam" or "lob" or "pounce" or "tongue" or "bite" or "throw" or "leap" or "charge" or "roar" or "hop";

    private void UpdateJuice(float dt)
    {
        if (Juice <= 0 || dt <= 0) return;
        var rest = _once != null && IsWindup(_once) ? Vector2.One + new Vector2(0.16f, -0.18f) * Juice : Vector2.One;
        // an under-damped spring: overshoots a little, which reads as energetic. Integrated in
        // small steps so one long frame can't make it explode.
        float left = Math.Min(dt, 0.1f);
        while (left > 0f)
        {
            float h = Math.Min(left, 1f / 120f);
            var acc = (rest - _punch) * 320f - _punchVel * 16f;
            _punchVel += acc * h;
            _punch += _punchVel * h;
            left -= h;
        }
        _motion = _motion.Lerp(_motionTarget, 1 - MathF.Exp(-dt * 14f));
        var k = _punch * _motion;
        var cur = Sprite.Scale;
        Sprite.Scale = new Vector2(Mathf.Sign(cur.X == 0 ? 1 : cur.X) * _baseMag.X * k.X, Mathf.Sign(cur.Y == 0 ? 1 : cur.Y) * _baseMag.Y * k.Y);
        Sprite.Position = new Vector2(0, FootOffset * (1 - k.Y));
    }

    public string Current => _once ?? _base;
    public bool OnceActive => _once != null;
    public string OnceName => _once;

    public static SpriteAnimator Create(string setName, float sizeMult = 1f)
    {
        var a = new SpriteAnimator();
        a.Init(setName, sizeMult);
        return a;
    }

    public void Init(string setName, float sizeMult = 1f)
    {
        Sheet = SpriteSet.Get(setName);
        _flashShader ??= new Shader
        {
            Code = @"shader_type canvas_item;
uniform float flash = 0.0;
uniform float brightness = 1.18;
uniform vec4 flash_color : source_color = vec4(1.0, 1.0, 1.0, 1.0);
void fragment() {
    vec4 c = texture(TEXTURE, UV) * COLOR;
    c.rgb = mix(c.rgb * brightness, flash_color.rgb, flash);
    COLOR = c;
}"
        };
        _mat = new ShaderMaterial { Shader = _flashShader };
        Sprite = new AnimatedSprite2D
        {
            SpriteFrames = Sheet.Frames,
            Centered = false,
            Offset = -Sheet.Origin,
            Scale = Vector2.One * (sizeMult / Sheet.Scale),
            Material = _mat,
            TextureFilter = TextureFilterEnum.Linear,
        };
        AddChild(Sprite);
        Sprite.AnimationFinished += OnFinished;
        _baseMag = Vector2.One * (sizeMult / Sheet.Scale);
        _size = sizeMult;
        // What you actually see: the 3D model of this creature, posed from this animator's clips.
        Model3D = CreatureModel.Create(setName);
        if (Model3D != null) AddChild(Model3D);
    }

    /// <summary>The 3D model this animator drives (null for sets without one yet).</summary>
    public CreatureModel Model3D { get; private set; }
    private CreatureModel _formModel;
    private string _formSet;
    private float _formSize = 1f;
    /// <summary>A Shape Shifter's attack clip on the form's model (the creature's own wind-up and strike), and how far along it is; null otherwise.</summary>
    public string FormClip;
    public float FormClipT;

    /// <summary>The Shape Shifter becomes a creature (its model replaces the hero's, scaled) or is itself again (null).</summary>
    public void SetForm(string set, float size = 1f)
    {
        if (set == _formSet) { _formSize = size; return; }
        _formSet = set;
        _formSize = size;
        if (_formModel != null) { _formModel.QueueFree(); _formModel = null; }
        if (set != null)
        {
            _formModel = CreatureModel.Create(set);
            if (_formModel != null) AddChild(_formModel);
        }
        if (Model3D != null) Model3D.Visible = _formModel == null;
    }
    private float _size = 1f;
    private float _animTime, _clipTime;
    private string _clipKey = "";
    private Color _flashColor = Colors.White;

    public float SizeMult
    {
        set
        {
            _size = value;
            _baseMag = Vector2.One * (value / Sheet.Scale);
            Sprite.Scale = new Vector2(Mathf.Sign(Sprite.Scale.X == 0 ? 1 : Sprite.Scale.X), Mathf.Sign(Sprite.Scale.Y == 0 ? 1 : Sprite.Scale.Y)) * (value / Sheet.Scale);
        }
    }

    /// <summary>
    /// Mirrors this frame's animation state onto the 3D model: clip and progress (the sprite
    /// sheet's frames stay the clock, so hitboxes and poses stay in step), facing, squash and
    /// stretch, roll, hit flash, biome tint, and fading or burning away.
    /// </summary>
    private void Sync3D(float dt)
    {
        var m = _formModel ?? Model3D;
        if (m == null) return;
        if (_formModel != null && Model3D != null) Model3D.Visible = false;
        bool shown = Visible;
        for (Node n = GetParent(); shown && n != null && n != G.World; n = n.GetParent())
            if (n is CanvasItem ci && !ci.Visible) shown = false;
        m.Visible = shown;
        if (!shown) return;

        string anim = Sprite.Animation;
        string clip = anim.EndsWith("_r") || anim.EndsWith("_l") ? anim[..^2] : anim;
        int frames = Math.Max(1, Sheet.Frames.GetFrameCount(anim));
        bool loop = Sheet.Frames.GetAnimationLoop(anim);
        float t = Math.Clamp((Sprite.Frame + Sprite.FrameProgress) / frames, 0f, 1f);
        float tdt = dt * TimeMult;
        _animTime += tdt;
        if (clip != _clipKey) { _clipKey = clip; _clipTime = 0f; }
        _clipTime += tdt;

        var owner = GetParent() as Node2D;
        var body = owner as CharacterBody2D;
        var vel = body?.Velocity ?? Vector2.Zero;
        float formT = t;
        if (_formModel != null && FormClip != null) { clip = FormClip; formT = FormClipT; }
        var input = new AnimInput
        {
            Clip = clip, Frame = Sprite.Frame, Frames = frames, T = formT, Loop = loop, Time = _animTime, Dt = tdt,
            Facing = Facing, Vel = new Vector2(vel.X, -vel.Y) / W3.Ppu,
            // (online copies go by what their own game says about their footing)
            OnFloor = owner switch { Player pl => pl.OnGround, Enemy en => en.OnGround, _ => body?.IsOnFloor() ?? false },
            InWater = G.Cave != null && G.Cave.IsWater(GlobalPosition), ClipTime = _clipTime, Owner = owner,
        };
        m.Face(Facing, clip, formT, dt);
        m.Animate(input);

        // squash and stretch (the sprite's springy scale) times the node's hit punch
        var ss = Sprite.Scale;
        var squash = new Vector2(MathF.Abs(ss.X) / Math.Max(1e-4f, _baseMag.X) * MathF.Abs(Scale.X), MathF.Abs(ss.Y) / Math.Max(1e-4f, _baseMag.Y) * MathF.Abs(Scale.Y));
        m.Position = W3.P(GlobalPosition);
        m.Scale = Vector3.One * (_size * (_formModel != null ? _formSize : 1f));
        m.UpdatePivot(squash, -GlobalRotation, FootOffset / W3.Ppu / Math.Max(0.01f, _size), ss.Y < 0);

        m.Design.Frame(m, input);
        m.SetFlash(Math.Min(1f, _flash), _flashColor);
        if (owner is Enemy foe) { m.SetAura(foe.AfflictionAura); m.SetInkTint(foe.StatusInk); }
        else if (owner is Player hero) { m.SetAura(hero.StatusAura); m.SetInkTint(hero.StatusInk); }
        var tint = Sprite.SelfModulate;
        m.SetTint(tint, tint.R > 0.99f && tint.G > 0.99f && tint.B > 0.99f ? 0f : 1f);
        float alpha = Modulate.A;
        if (clip == "death") { m.SetDissolve(1f - alpha); m.SetFade(1f); }
        else { m.SetDissolve(0f); m.SetFade(alpha); }
    }

    /// <summary>Mirror vertically (spiders on the ceiling). Left/right facing is unaffected.</summary>
    public bool FlipV
    {
        set { var s = Sprite.Scale; s.Y = Mathf.Abs(s.Y) * (value ? -1 : 1); Sprite.Scale = s; }
    }

    public bool Has(string name) => Sheet.Names.Contains(name) || Sheet.Names.Contains(name + "_r");

    /// <summary>Sets the looping animation for the current gameplay state.</summary>
    public void Loop(string name, float speed = 1f)
    {
        _base = name;
        BaseSpeed = speed;
    }

    /// <summary>Plays a one-shot over the base animation. Lower-priority requests don't interrupt.</summary>
    public bool Once(string name, int priority = 1, float speed = 1f, bool restart = true)
    {
        if (!Has(name)) return false;
        if (_once != null && priority < _oncePriority) return false;
        if (_once == name && !restart) return true;
        _once = name;
        _oncePriority = priority;
        _onceSpeed = speed;
        _turning = false;
        _manual = false;
        Apply(true);
        if (IsStrike(name)) Punch(new Vector2(0.8f, 1.26f));
        else if (name == "land") Punch(new Vector2(1.32f, 0.7f));
        else if (name is "jump" or "jump_start") Punch(new Vector2(0.82f, 1.24f));
        else if (name == "hurt") Punch(new Vector2(1.28f, 0.76f));
        return true;
    }

    public void CancelOnce()
    {
        _once = null;
        _turning = false;
    }

    /// <summary>Requests a facing. If it differs from what's shown and nothing important is playing, a turn animation bridges it.</summary>
    public void Face(int dir, bool instant = false)
    {
        if (dir == 0) return;
        _targetFacing = dir;
        if (dir == Facing && !_turning) return;
        if (_turning) return;
        bool canTurn = AllowTurns && !instant && (_once == null || _oncePriority <= 1) && Sheet.Names.Contains("turn_r2l");
        if (canTurn)
        {
            _once = dir < 0 ? "turn_r2l" : "turn_l2r";
            _oncePriority = 1;
            _onceSpeed = 1.3f;
            _turning = true;
            Facing = dir; // the turn clip ends in the new facing
            Apply(true);
        }
        else Facing = dir;
    }

    /// <summary>
    /// Online copies: shows exactly the animation another game's animator shows (its full name,
    /// facing included) from its frame, playing on at its speed. It only jumps when the clip
    /// changes or the frame has drifted, so playback stays smooth between updates.
    /// </summary>
    public void Mirror(string anim, int frame, float speed, int facing)
    {
        if (string.IsNullOrEmpty(anim) || !Sheet.Frames.HasAnimation(anim)) return;
        _manual = true;
        _once = null;
        Facing = facing < 0 ? -1 : 1;
        _targetFacing = Facing;
        int count = Sheet.Frames.GetFrameCount(anim);
        frame = Math.Clamp(frame, 0, Math.Max(0, count - 1));
        if (Sprite.Animation != anim)
        {
            Sprite.Play(anim);
            Sprite.Frame = frame;
        }
        else
        {
            int d = Math.Abs(Sprite.Frame - frame);
            if (d > 1 && d < count - 1) Sprite.Frame = frame;
            if (!Sprite.IsPlaying() && Sheet.Frames.GetAnimationLoop(anim)) Sprite.Play(anim);
        }
        Sprite.SpeedScale = speed;
    }

    /// <summary>Drive an animation's frame directly from gameplay time (e.g. the urchin's spike cycle).</summary>
    public void SetFrameManual(string name, float seconds)
    {
        _manual = true;
        string anim = Resolve(name);
        if (Sprite.Animation != anim) Sprite.Animation = anim;
        int count = Sheet.Frames.GetFrameCount(anim);
        float fps = (float)Sheet.Frames.GetAnimationSpeed(anim);
        Sprite.Stop();
        Sprite.Frame = Mathf.PosMod((int)(seconds * fps), count);
    }

    public void Flash(float amount = 1f) => _flash = Math.Max(_flash, amount);
    /// <summary>How strongly it's flashing right now (online: sent with the hero).</summary>
    public float FlashAmount => _flash;

    public Color FlashColor { set { _flashColor = value; _mat.SetShaderParameter("flash_color", value); } }

    private string Resolve(string name)
    {
        if (name.StartsWith("turn_")) return name;
        string suffixed = name + (Facing >= 0 ? "_r" : "_l");
        if (Sheet.Names.Contains(suffixed)) return suffixed;
        return Sheet.Names.Contains(name) ? name : Sprite.Animation;
    }

    private void Apply(bool restart)
    {
        if (_manual) return;
        string want = Resolve(Current);
        float speed = _once != null ? _onceSpeed : BaseSpeed;
        if (Sprite.Animation != want)
        {
            // keep the loop phase when only the facing changed (run_r -> run_l)
            int frame = Sprite.Frame;
            float progress = Sprite.FrameProgress;
            bool sameClip = Sprite.Animation.ToString().Length > 2 && want.Length > 2 &&
                            Sprite.Animation.ToString()[..^2] == want[..^2] && !restart;
            Sprite.Play(want);
            Sprite.SpeedScale = speed * TimeMult;
            if (sameClip && frame < Sheet.Frames.GetFrameCount(want)) Sprite.SetFrameAndProgress(frame, progress);
        }
        else
        {
            if (restart) { Sprite.Stop(); Sprite.Play(want); }
            Sprite.SpeedScale = speed * TimeMult;
        }
    }

    private void OnFinished()
    {
        if (_once == null) return;
        // death clips (priority 99) hold their last frame instead of returning to the idle loop
        if (_oncePriority >= 99) return;
        _once = null;
        _turning = false;
        if (_targetFacing != Facing) Face(_targetFacing);
        Apply(false);
    }

    public override void _Process(double delta)
    {
        UpdateJuice((float)delta * TimeMult);
        if (_flash > 0)
        {
            _mat.SetShaderParameter("flash", Math.Min(1f, _flash));
            _flash = Math.Max(0, _flash - (float)delta * 13f);
            if (_flash <= 0) _mat.SetShaderParameter("flash", 0f);
        }
        if (!_manual) Apply(false);
        Sync3D((float)delta);
    }

    /// <summary>
    /// Hands this sprite over to the world so its death animation can finish after the gameplay
    /// node is freed, then fades it out.
    /// </summary>
    public void PlayDeathAndFree(string anim = "death", float linger = 0.6f, Vector2 drift = default)
    {
        var pos = GlobalPosition;
        var rotation = GlobalRotation;
        var parent = GetParent();
        parent?.RemoveChild(this);
        G.World.AddChild(this);
        GlobalPosition = pos;
        GlobalRotation = rotation;
        ZIndex = 0;
        _manual = false;
        _once = null;
        CancelOnce();
        Once(anim, 99);
        var tw = CreateTween();
        float dur = Has(anim) ? Sheet.Frames.GetFrameCount(Resolve(anim)) / 24f : 0.3f;
        if (drift != Vector2.Zero) tw.Parallel().TweenProperty(this, "position", Position + drift, dur);
        tw.TweenInterval(Math.Max(0.05f, dur + linger - (drift != Vector2.Zero ? dur : 0)));
        tw.TweenProperty(this, "modulate:a", 0f, 0.5f);
        tw.TweenCallback(Callable.From(QueueFree));
    }

    /// <summary>The texture currently shown (for afterimages).</summary>
    public Texture2D CurrentTexture => Sheet.Frames.GetFrameTexture(Sprite.Animation, Sprite.Frame);
}

/// <summary>A fading copy of a sprite frame: dodge trails, dashes, heavy-hit echoes.</summary>
public partial class Afterimage : Sprite2D
{
    private float _life, _max;

    public static void Spawn(SpriteAnimator src, Color tint, float life = 0.22f)
    {
        if (src?.Sprite == null) return;
        if (src.Model3D != null) { Ghost3D.Spawn(src.Model3D, tint, life); return; }
        var a = new Afterimage
        {
            Texture = src.CurrentTexture,
            Centered = false,
            Offset = src.Sprite.Offset,
            Scale = src.Sprite.Scale,
            GlobalPosition = src.GlobalPosition,
            Rotation = src.GlobalRotation,
            Modulate = tint,
            ZIndex = 0,
            _life = life,
            _max = life,
        };
        G.World.AddChild(a);
    }

    public override void _Process(double delta)
    {
        _life -= (float)delta;
        if (_life <= 0) { QueueFree(); return; }
        var m = Modulate;
        m.A = _life / _max * 0.45f;
        Modulate = m;
    }
}
